impl BulkContraction<MultiVector> for AntiCircleOnOrigin {
    type Output = MultiVector;
    // Operative Statistics for this implementation:
    //           add/sub      mul      div      pow
    //      f32        5        9        0        0
    //    simd2        0        1        0      N/A
    //    simd3        0        3        0      N/A
    //    simd4        3        3        0      N/A
    // Totals...
    // yes simd        8       16        0      N/A
    //  no simd       17       32        0        0
    fn bulk_contraction(self, other: MultiVector) -> Self::Output {
        use crate::elements::*;
        let right_dual_g0 = other.group0().yx() * Simd32x2::from([-1.0, 1.0]);
        let right_dual_g9 = other.group1().wxyz() * Simd32x4::from([-1.0, 1.0, 1.0, 1.0]);
        MultiVector::from_groups(
            // scalar, e12345
            Simd32x2::from([
                (self[e41] * other[e15]) + (self[e42] * other[e25]) + (self[e43] * other[e35]) + (self[e23] * other[e23]) + (self[e31] * other[e31]) + (self[e12] * other[e12]),
                0.0,
            ]),
            // e1, e2, e3, e4
            Simd32x3::from(0.0).with_w((right_dual_g9[3] * self[e43]) * -1.0) + (self.group1().yzx() * right_dual_g9.wyz()).with_w(0.0)
                - (Simd32x4::from([other[e5], other[e5], other[e5], right_dual_g9[2] * self[e42]]) * self.group0().with_w(1.0))
                - (right_dual_g9.zwyy() * self.group1().zxy().with_w(self[e41])),
            // e5
            0.0,
            // e41, e42, e43, e45
            (Simd32x3::from(right_dual_g0[1]) * self.group0()).with_w(0.0),
            // e15, e25, e35
            Simd32x3::from(0.0),
            // e23, e31, e12
            Simd32x3::from(right_dual_g0[1]) * self.group1(),
            // e415, e425, e435, e321
            Simd32x4::from(0.0),
            // e423, e431, e412
            Simd32x3::from(0.0),
            // e235, e315, e125
            Simd32x3::from(0.0),
            // e1234, e4235, e4315, e4125
            Simd32x4::from(0.0),
            // e3215
            0.0,
        )
    }
}
