impl BulkContraction<MultiVector> for AntiDipoleInversionOnOrigin {
    type Output = MultiVector;
    // Operative Statistics for this implementation:
    //           add/sub      mul      div      pow
    //      f32        8       12        0        0
    //    simd2        0        1        0      N/A
    //    simd3        2        9        0      N/A
    //    simd4        4        3        0      N/A
    // Totals...
    // yes simd       14       25        0      N/A
    //  no simd       30       53        0        0
    fn bulk_contraction(self, other: MultiVector) -> Self::Output {
        use crate::elements::*;
        let right_dual_g0 = other.group0().yx() * Simd32x2::from([-1.0, 1.0]);
        let right_dual_g6_xyz = other.group5() * Simd32x3::from(-1.0);
        let right_dual_g8 = other.group4() * Simd32x3::from(-1.0);
        let right_dual_g9 = other.group1().wxyz() * Simd32x4::from([-1.0, 1.0, 1.0, 1.0]);
        let right_dual_g10 = other[e5] * -1.0;
        MultiVector::from_groups(
            // scalar, e12345
            Simd32x2::from([
                (right_dual_g10 * self[e4]) + (right_dual_g9[1] * self[e1]) + (right_dual_g9[2] * self[e2]) + (right_dual_g9[3] * self[e3]) + (self[e321] * other[e321])
                    - (self[e423] * other[e235])
                    - (self[e431] * other[e315])
                    - (self[e412] * other[e125]),
                0.0,
            ]),
            // e1, e2, e3, e4
            (Simd32x4::from(right_dual_g0[1]) * self.group1().yzwx())
                + Simd32x3::from(0.0).with_w(-(right_dual_g6_xyz[1] * self[e431]) - (right_dual_g6_xyz[2] * self[e412]))
                + (right_dual_g6_xyz * Simd32x3::from(self[e321])).with_w(0.0)
                + (right_dual_g8.yzx() * self.group0().zxy()).with_w(0.0)
                - (self.group0().yzxx() * right_dual_g8.zxy().with_w(right_dual_g6_xyz[0])),
            // e5
            0.0,
            // e41, e42, e43, e45
            ((self.group0().zxy() * right_dual_g9.zwy()) - (self.group0().yzx() * right_dual_g9.wyz())).with_w(0.0),
            // e15, e25, e35
            Simd32x3::from(0.0),
            // e23, e31, e12
            (Simd32x3::from(right_dual_g10) * self.group0().xyz()) - (Simd32x3::from(self[e321]) * right_dual_g9.yzw()),
            // e415, e425, e435, e321
            Simd32x3::from(0.0).with_w(right_dual_g0[1] * self[e321]),
            // e423, e431, e412
            Simd32x3::from(right_dual_g0[1]) * self.group0().xyz(),
            // e235, e315, e125
            Simd32x3::from(0.0),
            // e1234, e4235, e4315, e4125
            Simd32x4::from(0.0),
            // e3215
            0.0,
        )
    }
}
