impl BulkContraction<MultiVector> for AntiFlector {
    type Output = MultiVector;
    // Operative Statistics for this implementation:
    //           add/sub      mul      div      pow
    //      f32       10       15        0        0
    //    simd2        0        2        0      N/A
    //    simd3        3       10        0      N/A
    //    simd4        3        1        0      N/A
    // Totals...
    // yes simd       16       28        0      N/A
    //  no simd       31       53        0        0
    fn bulk_contraction(self, other: MultiVector) -> Self::Output {
        use crate::elements::*;
        let right_dual_g0 = other.group0().yx() * Simd32x2::from([-1.0, 1.0]);
        let right_dual_g6_xyz = other.group5() * Simd32x3::from(-1.0);
        let right_dual_g7 = other.group3().xyz() * Simd32x3::from(-1.0);
        let right_dual_g9 = other.group1().wxyz() * Simd32x4::from([-1.0, 1.0, 1.0, 1.0]);
        MultiVector::from_groups(
            // scalar, e12345
            Simd32x2::from([
                (right_dual_g9[0] * self[e5]) + (right_dual_g9[1] * self[e1]) + (right_dual_g9[2] * self[e2]) + (right_dual_g9[3] * self[e3]) + (self[e321] * other[e321])
                    - (self[e235] * other[e423])
                    - (self[e315] * other[e431])
                    - (self[e125] * other[e412]),
                0.0,
            ]),
            // e1, e2, e3, e4
            (right_dual_g6_xyz * Simd32x3::from(self[e321])).with_w(0.0)
                + (Simd32x3::from(right_dual_g0[1]) * self.group1().xyz()).with_w(0.0)
                + (right_dual_g7.zxy() * self.group0().yzx()).with_w(0.0)
                - (right_dual_g7.yzx() * self.group0().zxy()).with_w(0.0),
            // e5
            (right_dual_g0[1] * self[e5]) - (right_dual_g6_xyz[0] * self[e235]) - (right_dual_g6_xyz[1] * self[e315]) - (right_dual_g6_xyz[2] * self[e125]),
            // e41, e42, e43, e45
            Simd32x4::from(0.0),
            // e15, e25, e35
            (self.group0().yzx() * right_dual_g9.wyz()) + Simd32x2::from(0.0).with_z((right_dual_g9[1] * self[e315]) * -1.0)
                - (right_dual_g9.zw() * self.group0().zx()).with_z(0.0),
            // e23, e31, e12
            (Simd32x3::from(right_dual_g9[0]) * self.group0().xyz()) - (Simd32x3::from(self[e321]) * right_dual_g9.yzw()),
            // e415, e425, e435, e321
            Simd32x3::from(0.0).with_w(right_dual_g0[1] * self[e321]),
            // e423, e431, e412
            Simd32x3::from(0.0),
            // e235, e315, e125
            Simd32x3::from(right_dual_g0[1]) * self.group0().xyz(),
            // e1234, e4235, e4315, e4125
            Simd32x4::from(0.0),
            // e3215
            0.0,
        )
    }
}
