impl BulkContraction<MultiVector> for AntiMysteryCircleRotor {
    type Output = MultiVector;
    // Operative Statistics for this implementation:
    //           add/sub      mul      div      pow
    //      f32        4       12        0        0
    //    simd2        0        2        0      N/A
    //    simd3        2        2        0      N/A
    //    simd4        0        1        0      N/A
    // Totals...
    // yes simd        6       17        0      N/A
    //  no simd       10       26        0        0
    fn bulk_contraction(self, other: MultiVector) -> Self::Output {
        use crate::elements::*;
        let right_dual_g0 = other.group0().yx() * Simd32x2::from([-1.0, 1.0]);
        let right_dual_g9 = other.group1().wxyz() * Simd32x4::from([-1.0, 1.0, 1.0, 1.0]);
        MultiVector::from_groups(
            // scalar, e12345
            Simd32x2::from([
                (right_dual_g0[1] * self[scalar]) + (self[e23] * other[e23]) + (self[e31] * other[e31]) + (self[e12] * other[e12]) - (self[e45] * other[e45]),
                0.0,
            ]),
            // e1, e2, e3, e4
            ((self.group0().yzx() * right_dual_g9.wyz()) + Simd32x2::from(0.0).with_z(right_dual_g9[1] * self[e31] * -1.0) - (right_dual_g9.zw() * self.group0().zx()).with_z(0.0))
                .with_w(right_dual_g9[0] * self[e45] * -1.0),
            // e5
            self[e45] * other[e5] * -1.0,
            // e41, e42, e43, e45
            Simd32x3::from(0.0).with_w(right_dual_g0[1] * self[e45]),
            // e15, e25, e35
            Simd32x3::from(0.0),
            // e23, e31, e12
            Simd32x3::from(right_dual_g0[1]) * self.group0().xyz(),
            // e415, e425, e435, e321
            Simd32x4::from(0.0),
            // e423, e431, e412
            Simd32x3::from(0.0),
            // e235, e315, e125
            Simd32x3::from(0.0),
            // e1234, e4235, e4315, e4125
            Simd32x4::from(0.0),
            // e3215
            0.0,
        )
    }
}
