impl BulkContraction<MultiVector> for AntiMysteryDipoleInversion {
    type Output = MultiVector;
    // Operative Statistics for this implementation:
    //           add/sub      mul      div      pow
    //      f32       11       17        0        0
    //    simd2        0        1        0      N/A
    //    simd3        0        6        0      N/A
    //    simd4        3        3        0      N/A
    // Totals...
    // yes simd       14       27        0      N/A
    //  no simd       23       49        0        0
    fn bulk_contraction(self, other: MultiVector) -> Self::Output {
        use crate::elements::*;
        let right_dual_g0 = other.group0().yx() * Simd32x2::from([-1.0, 1.0]);
        let right_dual_g5 = other.group6().xyz();
        let right_dual_g7 = other.group3().xyz() * Simd32x3::from(-1.0);
        let right_dual_g9 = other.group1().wxyz() * Simd32x4::from([-1.0, 1.0, 1.0, 1.0]);
        MultiVector::from_groups(
            // scalar, e12345
            Simd32x2::from([
                (right_dual_g9[1] * self[e1]) + (right_dual_g9[2] * self[e2]) + (right_dual_g9[3] * self[e3]) + (self[e321] * other[e321])
                    - (right_dual_g5[0] * self[e415])
                    - (right_dual_g5[1] * self[e425])
                    - (right_dual_g5[2] * self[e435]),
                0.0,
            ]),
            // e1, e2, e3, e4
            Simd32x3::from(0.0).with_w(-(right_dual_g7[1] * self[e425]) - (right_dual_g7[2] * self[e435]))
                + (Simd32x3::from(right_dual_g0[1]) * self.group1()).with_w(0.0)
                + (Simd32x3::from(other[e45]) * self.group0().xyz()).with_w(0.0)
                - (self.group0().wwwx() * other.group5().with_w(right_dual_g7[0])),
            // e5
            (self[e415] * other[e15]) + (self[e425] * other[e25]) + (self[e435] * other[e35]),
            // e41, e42, e43, e45
            (Simd32x3::from(right_dual_g9[0]) * self.group0().xyz()).with_w(-(right_dual_g9[1] * self[e415]) - (right_dual_g9[2] * self[e425]) - (right_dual_g9[3] * self[e435])),
            // e15, e25, e35
            Simd32x3::from(other[e5] * -1.0) * self.group0().xyz(),
            // e23, e31, e12
            Simd32x3::from(self[e321] * -1.0) * right_dual_g9.yzw(),
            // e415, e425, e435, e321
            Simd32x4::from(right_dual_g0[1]) * self.group0(),
            // e423, e431, e412
            Simd32x3::from(0.0),
            // e235, e315, e125
            Simd32x3::from(0.0),
            // e1234, e4235, e4315, e4125
            Simd32x4::from(0.0),
            // e3215
            0.0,
        )
    }
}
