impl BulkContraction<MultiVector> for DipoleOnOrigin {
    type Output = MultiVector;
    // Operative Statistics for this implementation:
    //           add/sub      mul      div      pow
    //      f32        6       11        0        0
    //    simd2        0        1        0      N/A
    //    simd4        0        2        0      N/A
    // Totals...
    // yes simd        6       14        0      N/A
    //  no simd        6       21        0        0
    fn bulk_contraction(self, other: MultiVector) -> Self::Output {
        use crate::elements::*;
        let right_dual_g9 = other.group1().wxyz() * Simd32x4::from([-1.0, 1.0, 1.0, 1.0]);
        let right_dual_g10 = other[e5] * -1.0;
        MultiVector::from_groups(
            // scalar, e12345
            Simd32x2::from([(self[e41] * other[e15]) + (self[e42] * other[e25]) + (self[e43] * other[e35]) - (self[e45] * other[e45]), 0.0]),
            // e1, e2, e3, e4
            (Simd32x2::from(right_dual_g10) * self.group0().xy()).with_zw(
                right_dual_g10 * self[e43],
                -(right_dual_g9[0] * self[e45]) - (right_dual_g9[1] * self[e41]) - (right_dual_g9[2] * self[e42]) - (right_dual_g9[3] * self[e43]),
            ),
            // e5
            right_dual_g10 * self[e45],
            // e41, e42, e43, e45
            Simd32x4::from(other[scalar]) * self.group0(),
            // e15, e25, e35
            Simd32x3::from(0.0),
            // e23, e31, e12
            Simd32x3::from(0.0),
            // e415, e425, e435, e321
            Simd32x4::from(0.0),
            // e423, e431, e412
            Simd32x3::from(0.0),
            // e235, e315, e125
            Simd32x3::from(0.0),
            // e1234, e4235, e4315, e4125
            Simd32x4::from(0.0),
            // e3215
            0.0,
        )
    }
}
