impl BulkContraction<MultiVector> for MysteryDipoleInversion {
    type Output = MultiVector;
    // Operative Statistics for this implementation:
    //           add/sub      mul      div      pow
    //      f32       12       23        0        0
    //    simd2        0        1        0      N/A
    //    simd3        3       15        0      N/A
    //    simd4        6        3        0      N/A
    // Totals...
    // yes simd       21       42        0      N/A
    //  no simd       45       82        0        0
    fn bulk_contraction(self, other: MultiVector) -> Self::Output {
        use crate::elements::*;
        let right_dual_g0 = other.group0().yx() * Simd32x2::from([-1.0, 1.0]);
        let right_dual_g1 = other.group9().yzwx() * Simd32x4::from([-1.0, -1.0, -1.0, 1.0]);
        let right_dual_g5 = other.group6().xyz();
        let right_dual_g7 = other.group3().xyz() * Simd32x3::from(-1.0);
        let right_dual_g8 = other.group4() * Simd32x3::from(-1.0);
        let right_dual_g9 = other.group1().wxyz() * Simd32x4::from([-1.0, 1.0, 1.0, 1.0]);
        let right_dual_g10 = other[e5] * -1.0;
        MultiVector::from_groups(
            // scalar, e12345
            Simd32x2::from([
                (right_dual_g1[0] * self[e4235])
                    + (right_dual_g1[1] * self[e4315])
                    + (right_dual_g1[2] * self[e4125])
                    + (other[e23] * self[e23])
                    + (other[e31] * self[e31])
                    + (other[e12] * self[e12])
                    - (other[e45] * self[e45]),
                0.0,
            ]),
            // e1, e2, e3, e4
            Simd32x3::from(0.0).with_w((other[e431] * self[e4315]) + (other[e412] * self[e4125]))
                + (right_dual_g5.zxy() * self.group1().yzx()).with_w(other[e423] * self[e4235])
                + (self.group0().yzx() * right_dual_g9.wyz()).with_w(0.0)
                - (right_dual_g9.zwyx() * self.group0().zxyw())
                - (right_dual_g5.yzx() * self.group1().zxy()).with_w(0.0),
            // e5
            (right_dual_g10 * self[e45]) - (other[e235] * self[e4235]) - (other[e315] * self[e4315]) - (other[e125] * self[e4125]),
            // e41, e42, e43, e45
            Simd32x3::from(0.0).with_w((other[e23] * self[e4235]) + (other[e31] * self[e4315]) + (other[e12] * self[e4125]))
                + (right_dual_g7.zxy() * self.group1().yzx()).with_w(right_dual_g0[1] * self[e45])
                - (right_dual_g7.yzx() * self.group1().zxy()).with_w(0.0),
            // e15, e25, e35
            (right_dual_g8.yzx() * self.group1().zxy()) - (right_dual_g8.zxy() * self.group1().yzx()),
            // e23, e31, e12
            (Simd32x3::from(right_dual_g0[1]) * self.group0().xyz()) - (Simd32x3::from(other[e45]) * self.group1()),
            // e415, e425, e435, e321
            ((self.group1().zxy() * right_dual_g9.zwy()) - (self.group1().yzx() * right_dual_g9.wyz())).with_w(0.0),
            // e423, e431, e412
            Simd32x3::from(right_dual_g9[0] * -1.0) * self.group1(),
            // e235, e315, e125
            Simd32x3::from(right_dual_g10) * self.group1(),
            // e1234, e4235, e4315, e4125
            Simd32x4::from([0.0, right_dual_g0[1] * self[e4235], right_dual_g0[1] * self[e4315], right_dual_g0[1] * self[e4125]]),
            // e3215
            0.0,
        )
    }
}
