    //  no simd       59      101        0        0
    fn bulk_contraction(self, other: MultiVector) -> Self::Output {
        use crate::elements::*;
        let right_dual_g0 = other.group0().yx() * Simd32x2::from([-1.0, 1.0]);
        let right_dual_g1 = other.group9().yzwx() * Simd32x4::from([-1.0, -1.0, -1.0, 1.0]);
        let right_dual_g3_w = other[e321] * -1.0;
        let right_dual_g5 = other.group6().xyz();
        let right_dual_g6_xyz = other.group5() * Simd32x3::from(-1.0);
        let right_dual_g7 = other.group3().xyz() * Simd32x3::from(-1.0);
        let right_dual_g8 = other.group4() * Simd32x3::from(-1.0);
        let right_dual_g9 = other.group1().wxyz() * Simd32x4::from([-1.0, 1.0, 1.0, 1.0]);
        let right_dual_g10 = other[e5] * -1.0;
        MultiVector::from_groups(
            // scalar, e12345
            Simd32x2::from([
                (right_dual_g1[0] * self[e4235])
                    + (right_dual_g1[1] * self[e4315])
                    + (right_dual_g1[2] * self[e4125])
                    + (right_dual_g1[3] * self[e3215])
                    + (other[e3215] * self[e1234]),
                0.0,
            ]),
            // e1, e2, e3, e4
            (Simd32x4::from(self[e1234]) * other.group8().with_w(right_dual_g3_w))
                + (self.group0().yzxx() * right_dual_g5.zxy().with_w(other[e423]))
                + Simd32x3::from(0.0).with_w((other[e431] * self[e4315]) + (other[e412] * self[e4125]))
                - (Simd32x3::from(self[e3215]) * other.group7()).with_w(0.0)
                - (right_dual_g5.yzx() * self.group0().zxy()).with_w(0.0),
            // e5
            -(right_dual_g3_w * self[e3215]) - (other[e235] * self[e4235]) - (other[e315] * self[e4315]) - (other[e125] * self[e4125]),
            // e41, e42, e43, e45
            Simd32x3::from(0.0).with_w(-(right_dual_g6_xyz[1] * self[e4315]) - (right_dual_g6_xyz[2] * self[e4125]))
                + (right_dual_g6_xyz * Simd32x3::from(self[e1234])).with_w(0.0)
                + (right_dual_g7.zxy() * self.group0().yzx()).with_w(0.0)
                - (self.group0().zxyx() * right_dual_g7.yzx().with_w(right_dual_g6_xyz[0])),
            // e15, e25, e35
            (right_dual_g6_xyz * Simd32x3::from(self[e3215])) + (right_dual_g8.yzx() * self.group0().zxy()) - (right_dual_g8.zxy() * self.group0().yzx()),
            // e23, e31, e12
            (right_dual_g7 * Simd32x3::from(self[e3215])) + (right_dual_g8 * Simd32x3::from(self[e1234])) - (Simd32x3::from(other[e45]) * self.group0().xyz()),
            // e415, e425, e435, e321
            (self.group0().zxy() * right_dual_g9.zwy()).with_w(right_dual_g10 * self[e1234]) - (right_dual_g9.wyzx() * self.group0().yzxw()),
            // e423, e431, e412
            (Simd32x3::from(self[e1234]) * right_dual_g9.yzw()) - (Simd32x3::from(right_dual_g9[0]) * self.group0().xyz()),
            // e235, e315, e125
            (Simd32x3::from(right_dual_g10) * self.group0().xyz()) - (Simd32x3::from(self[e3215]) * right_dual_g9.yzw()),
            // e1234, e4235, e4315, e4125
            Simd32x4::from(right_dual_g0[1]) * Simd32x4::from([self[e1234], self[e4235], self[e4315], self[e4125]]),
            // e3215
            right_dual_g0[1] * self[e3215],
        )
    }
