impl BulkContraction<MultiVector> for SphereAtOrigin {
    type Output = MultiVector;
    // Operative Statistics for this implementation:
    //           add/sub      mul      div      pow
    //      f32        2       11        0        0
    //    simd2        0        1        0      N/A
    //    simd3        2        9        0      N/A
    //    simd4        0        1        0      N/A
    // Totals...
    // yes simd        4       22        0      N/A
    //  no simd        8       44        0        0
    fn bulk_contraction(self, other: MultiVector) -> Self::Output {
        use crate::elements::*;
        let right_dual_g0 = other.group0().yx() * Simd32x2::from([-1.0, 1.0]);
        let right_dual_g3_w = other[e321] * -1.0;
        let right_dual_g6 = (other.group5() * Simd32x3::from(-1.0)).with_w(other[e45]);
        let right_dual_g9 = other.group1().wxyz() * Simd32x4::from([-1.0, 1.0, 1.0, 1.0]);
        MultiVector::from_groups(
            // scalar, e12345
            Simd32x2::from([(other[e1234] * self[e3215]) + (other[e3215] * self[e1234]), 0.0]),
            // e1, e2, e3, e4
            ((Simd32x3::from(self[e1234]) * other.group8()) - (Simd32x3::from(self[e3215]) * other.group7())).with_w(right_dual_g3_w * self[e1234]),
            // e5
            right_dual_g3_w * self[e3215] * -1.0,
            // e41, e42, e43, e45
            (Simd32x3::from(self[e1234]) * right_dual_g6.xyz()).with_w(0.0),
            // e15, e25, e35
            Simd32x3::from(self[e3215]) * right_dual_g6.xyz(),
            // e23, e31, e12
            -(Simd32x3::from(self[e3215]) * other.group3().xyz()) - (Simd32x3::from(self[e1234]) * other.group4()),
            // e415, e425, e435, e321
            Simd32x3::from(0.0).with_w(-(right_dual_g9[0] * self[e3215]) - (other[e5] * self[e1234])),
            // e423, e431, e412
            Simd32x3::from(self[e1234]) * right_dual_g9.yzw(),
            // e235, e315, e125
            Simd32x3::from(self[e3215] * -1.0) * right_dual_g9.yzw(),
            // e1234, e4235, e4315, e4125
            Simd32x4::from([right_dual_g0[1] * self[e1234], 0.0, 0.0, 0.0]),
            // e3215
            right_dual_g0[1] * self[e3215],
        )
    }
}
